        // Return-change preference: more compact More Farming bundles when
        // available; otherwise use mod stacks. Native x5/x12 are fallbacks.
        public static ushort PreferredRefund(ushort baseId,int units)
        {
            List<BundleVariant> list=ForBase(baseId);
            if (list==null) return 0;
            ushort best=0;int rank=int.MaxValue;
            foreach (BundleVariant b in list)
            {
                if (b.Units!=units || !IsAvailable(b.Id)) continue;
                int priority=((b.Id>=49100 && b.Id<=49150) || (b.Id>=48132 && b.Id<=48180)) ? 0 :
                             b.Id>=10000 ? 1 : 2;
                if (priority<rank) { best=b.Id;rank=priority; }
            }
